      "ballot_id": "B007",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence, making fault-tolerant quantum computation physically plausible. Its conceptual and practical influence is exceptional.",
        "attribution": "Shor and Steane introduced landmark codes, while Kitaev developed the topological approach. These are distinct foundational contributions within a broader international effort.",
        "maturity": "The theory is established and its principles have been demonstrated across platforms. Large-scale fault-tolerant operation remains a work in progress, but the foundational achievement is mature.",
        "uncertainties": [
          "The boundary between foundational theory and later experimental realization complicates the scope of a prize."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation provides a powerful account of the early universe and the origin of primordial structure, with deep consequences for cosmology and fundamental physics.",
        "attribution": "Guth and Linde developed central inflationary frameworks; Mukhanov made seminal contributions to the theory of cosmological perturbations and their observable consequences.",
        "maturity": "The framework has substantial indirect support from cosmological observations, but no unique inflationary model has been established.",
        "uncertainties": [
          "Inflation remains a family of models, and the underlying physical mechanism has not been directly identified."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "The gauge/gravity correspondence has profoundly reshaped quantum field theory and the study of quantum gravity, opening productive connections between fields that had seemed separate.",
        "attribution": "Maldacena proposed the sharp correspondence; Witten and Polyakov made major contributions to its development and the broader holographic framework.",
        "maturity": "The conjecture is exceptionally influential and has passed many nontrivial theoretical tests, though its physical interpretation as a description of our universe is unsettled.",
        "uncertainties": [
          "The correspondence is not experimentally confirmed as a description of nature.",
          "Credit for the broader holographic principle and its development is wider than three individuals."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned fundamental quantum principles into a new way to establish secure communication and helped create quantum information as a major field.",
        "attribution": "Bennett and Brassard developed the influential BB84 protocol; Ekert introduced an entanglement-based approach that made the connection to Bell tests especially clear.",
        "maturity": "The protocols are well understood and have been implemented in many settings. Practical systems face engineering and security constraints, but the foundational physics is settled.",
        "uncertainties": [
          "The extent to which practical security depends on idealized assumptions varies between implementations."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory and its exact results became a lasting foundation for critical phenomena and for later developments across statistical physics and field theory.",
        "attribution": "Belavin, Polyakov, and Zamolodchikov established a central body of exact results and methods; the wider development of conformal theory involved many contributors.",
        "maturity": "The results have been repeatedly used and extended over decades, with lasting influence across physics and mathematics.",
        "uncertainties": [
          "The proposed discovery spans a broad body of work, making a precise prize citation and boundary of credit important."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks enable extraordinary precision and control, with significance for tests of fundamental physics, timekeeping, and precision measurement.",
        "attribution": "Katori and Ye independently developed leading approaches that established the field; the wider clock community contributed substantially to subsequent performance.",
        "maturity": "The technique is experimentally mature, reproducible across laboratories, and improving rapidly.",
        "uncertainties": [
          "The relative weight of the initial proposals, demonstrations, and later precision advances would need careful attribution."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Shigeru Yoshida"
      ],
      "assessment": {
        "nobel_worthiness": "High-energy neutrino astronomy opened a new observational window on the universe and established that neutrinos can reveal sources inaccessible to conventional telescopes.",
        "attribution": "Halzen was central to the detector vision and scientific program; Karle and Yoshida made major contributions to building and operating IceCube and establishing its results. Credit is inherently collaborative.",
        "maturity": "The high-energy neutrino signal and its astrophysical significance have been established, although identifying and characterizing individual sources remains an active task.",
        "uncertainties": [
          "The scale of the collaboration makes individual attribution difficult.",
          "The sources responsible for much of the diffuse neutrino flux remain uncertain."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Connecting gamma-ray bursts to afterglows and distant cosmological sources transformed high-energy astronomy and established a new way to study extreme events across cosmic time.",
        "attribution": "Costa and Frontera were central to the BeppoSAX observations that enabled rapid localization; Kulkarni led early optical follow-up that established the afterglow and cosmological interpretation.",
        "maturity": "The observational breakthrough and cosmological nature of many bursts are firmly established, with decades of follow-up and independent confirmation.",
        "uncertainties": [
          "The discovery unfolded through instrument teams and rapid international follow-up, so the exact division of decisive credit is difficult to reduce to three people."
        ]
      }
    }
  ]
